CREATE TABLE IF NOT EXISTS "bpm_user_group" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "name" varchar(63) NOT NULL,
    "description" varchar(255) NOT NULL,
    "status" tinyint NOT NULL,
    "user_ids" varchar(255) NOT NULL,
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    PRIMARY KEY ("id")
) COMMENT '用户组';

CREATE TABLE IF NOT EXISTS "bpm_category" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "name" varchar(63) NOT NULL,
    "code" varchar(63) NOT NULL,
    "description" varchar(255) NOT NULL,
    "status" tinyint NOT NULL,
    "sort" int NOT NULL,
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    PRIMARY KEY ("id")
) COMMENT '分类';

CREATE TABLE IF NOT EXISTS "bpm_form" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "name" varchar(63) NOT NULL,
    "status" tinyint NOT NULL,
    "fields" varchar(255) NOT NULL,
    "conf" varchar(255) NOT NULL,
    "remark" varchar(255),
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    PRIMARY KEY ("id")
) COMMENT '动态表单';

CREATE TABLE IF NOT EXISTS "bpm_approval_signature_record" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "module_code" varchar(64) NOT NULL,
    "source_task_type" varchar(128) NOT NULL,
    "source_task_id" varchar(128) DEFAULT NULL,
    "business_key" varchar(128) DEFAULT NULL,
    "process_instance_id" varchar(128) DEFAULT NULL,
    "signer_user_id" bigint NOT NULL,
    "review_result" varchar(32) NOT NULL,
    "reason" varchar(500) DEFAULT NULL,
    "password_verified" bit NOT NULL DEFAULT TRUE,
    "signature_image_id" bigint DEFAULT NULL,
    "signature_image_version_no" int DEFAULT NULL,
    "signature_image_file_id" bigint DEFAULT NULL,
    "signature_image_file_url" varchar(512) DEFAULT NULL,
    "signature_image_sha256" varchar(128) DEFAULT NULL,
    "signature_image_content_type" varchar(128) DEFAULT NULL,
    "signature_image_file_size" bigint DEFAULT NULL,
    "signature_image_status_snapshot" varchar(32) DEFAULT NULL,
    "signature_image_verified_status" varchar(32) DEFAULT NULL,
    "signed_at" timestamp NOT NULL,
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT 0,
    PRIMARY KEY ("id")
) COMMENT '统一审批电子签名记录';

CREATE TABLE IF NOT EXISTS "bpm_form_template_version" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "template_id" bigint,
    "tenant_id" bigint NOT NULL DEFAULT 0,
    "template_name" varchar(128) NOT NULL,
    "version_no" varchar(64) NOT NULL,
    "status" varchar(32) NOT NULL,
    "source_file_name" varchar(255) NOT NULL,
    "source_file_content" clob,
    "recognized_schema_json" clob,
    "jimu_schema_json" clob,
    "remark" varchar(500),
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    PRIMARY KEY ("id")
) COMMENT '表单中心模板版本';

CREATE TABLE IF NOT EXISTS "bpm_form_action_policy" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "tenant_id" bigint NOT NULL,
    "data_domain" varchar(64) NOT NULL,
    "system_code" varchar(64) NOT NULL,
    "object_type" varchar(64) NOT NULL,
    "action_code" varchar(64) NOT NULL,
    "object_state" varchar(64) NOT NULL,
    "policy_type" varchar(32) NOT NULL,
    "approval_mode" varchar(32) NOT NULL DEFAULT 'BPM_REQUIRED',
    "bpm_process_key" varchar(128),
    "effect_executor_code" varchar(128),
    "status" varchar(32) NOT NULL,
    "slots_json" clob,
    "remark" varchar(500),
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    PRIMARY KEY ("id")
) COMMENT '表单中心业务动作策略';

CREATE TABLE IF NOT EXISTS "bpm_form_action_instance" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "instance_code" varchar(128) NOT NULL,
    "tenant_id" bigint NOT NULL,
    "policy_id" bigint NOT NULL,
    "applicant_user_id" bigint NOT NULL,
    "status" varchar(32) NOT NULL,
    "data_domain" varchar(64) NOT NULL,
    "system_code" varchar(64) NOT NULL,
    "object_type" varchar(64) NOT NULL,
    "object_id" varchar(128) NOT NULL,
    "object_version" varchar(128) NOT NULL,
    "action_code" varchar(64) NOT NULL,
    "object_state" varchar(64) NOT NULL,
    "idempotency_key" varchar(128) NOT NULL,
    "business_context_json" clob NOT NULL,
    "form_data_json" clob,
    "bpm_process_instance_id" varchar(128),
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    PRIMARY KEY ("id")
) COMMENT '表单中心实例';

CREATE TABLE IF NOT EXISTS "bpm_form_action_snapshot" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "instance_id" bigint NOT NULL,
    "tenant_id" bigint NOT NULL,
    "snapshot_type" varchar(32) NOT NULL,
    "snapshot_version" int NOT NULL,
    "form_data_json" clob,
    "business_context_json" clob NOT NULL,
    "attachment_ids_json" clob,
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    PRIMARY KEY ("id")
) COMMENT 'form center action snapshot';

CREATE TABLE IF NOT EXISTS "bpm_form_task_permission" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "instance_id" bigint NOT NULL,
    "tenant_id" bigint NOT NULL,
    "bpm_process_instance_id" varchar(128) NOT NULL,
    "task_id" varchar(128) NOT NULL,
    "user_id" bigint NOT NULL,
    "permission_codes_json" clob NOT NULL,
    "status" varchar(32) NOT NULL,
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    PRIMARY KEY ("id")
) COMMENT 'form center active task permission';

CREATE TABLE IF NOT EXISTS "bpm_form_effect_execution" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "instance_id" bigint NOT NULL,
    "tenant_id" bigint NOT NULL,
    "execution_code" varchar(128) NOT NULL,
    "idempotency_key" varchar(128) NOT NULL,
    "status" varchar(32) NOT NULL,
    "result_ref" varchar(255),
    "failure_reason" varchar(500),
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    PRIMARY KEY ("id")
) COMMENT 'form center effect execution';

CREATE TABLE IF NOT EXISTS "bpm_business_approval_policy" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "tenant_id" bigint NOT NULL,
    "data_domain" varchar(64) NOT NULL,
    "system_code" varchar(64) NOT NULL,
    "object_type" varchar(64) NOT NULL,
    "action_code" varchar(64) NOT NULL,
    "object_state" varchar(64) NOT NULL,
    "policy_mode" varchar(32) NOT NULL,
    "process_definition_key" varchar(128),
    "effect_executor_code" varchar(128) NOT NULL,
    "status" varchar(32) NOT NULL,
    "remark" varchar(500),
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    PRIMARY KEY ("id")
) COMMENT 'business approval policy';

CREATE TABLE IF NOT EXISTS "bpm_business_approval_request" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "tenant_id" bigint NOT NULL,
    "policy_id" bigint NOT NULL,
    "policy_mode" varchar(32) NOT NULL,
    "data_domain" varchar(64) NOT NULL,
    "system_code" varchar(64) NOT NULL,
    "object_type" varchar(64) NOT NULL,
    "object_id" varchar(128) NOT NULL,
    "object_version" varchar(128) NOT NULL,
    "action_code" varchar(64) NOT NULL,
    "object_state" varchar(64) NOT NULL,
    "request_status" varchar(32) NOT NULL,
    "applicant_user_id" bigint NOT NULL,
    "process_definition_key" varchar(128),
    "process_instance_id" varchar(128),
    "effect_executor_code" varchar(128) NOT NULL,
    "last_event_key" varchar(256),
    "result_state" varchar(64),
    "failure_reason" varchar(500),
    "business_context_json" clob NOT NULL,
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    PRIMARY KEY ("id")
) COMMENT 'business approval request';
